namespace Pulse.WebApi.Tests.Features.Media.Documents;

using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Text;
using FluentAssertions;
using Pulse.WebApi.Data.Entities;
using Pulse.WebApi.Features.Media;
using Pulse.WebApi.Features.Media.Documents;
using Xunit;

/// <summary>
/// press-room story 02 AC "Corpus test" and AC "Deny-list scan": the checked-in hostile-PDF corpus
/// (<c>Corpus/*.pdf</c>, regenerated by <c>Corpus/generate_corpus.py</c>) run through the sniffer and the REAL scanner,
/// each file with its pinned verdict — including the documented known miss (JS inside a compressed object stream),
/// which is ACCEPTED and asserted as such so the limitation is explicit rather than assumed. Pure; no host, no Docker.
/// </summary>
public sealed class DocumentScanCorpusTests
{
    /// <summary>Accepted by the scan (sniffed as a document first).</summary>
    private const string Accepted = "accepted";

    /// <summary>Refused by the sniffer (415) — never reaches the scan.</summary>
    private const string NotAPdf = "not-a-pdf";

    /// <summary>Every corpus file and its pinned verdict. Adding a file to the corpus without a line here fails.</summary>
    private static readonly IReadOnlyDictionary<string, string> Expected = new Dictionary<string, string>(StringComparer.Ordinal)
    {
        ["benign-minimal.pdf"] = Accepted,
        ["benign-binary-streams.pdf"] = Accepted,
        ["benign-pjl-prefix.pdf"] = Accepted,
        ["js-openaction.pdf"] = DocumentRejectionReasons.ActiveContent,
        ["js-names-tree.pdf"] = DocumentRejectionReasons.ActiveContent,
        ["js-link-rendition.pdf"] = DocumentRejectionReasons.ActiveContent,
        ["aa-page.pdf"] = DocumentRejectionReasons.ActiveContent,
        ["launch.pdf"] = DocumentRejectionReasons.ActiveContent,
        ["submitform.pdf"] = DocumentRejectionReasons.ActiveContent,
        ["importdata.pdf"] = DocumentRejectionReasons.ActiveContent,
        ["gotoe.pdf"] = DocumentRejectionReasons.ActiveContent,
        ["richmedia.pdf"] = DocumentRejectionReasons.ActiveContent,
        ["xfa.pdf"] = DocumentRejectionReasons.ActiveContent,
        ["embedded-file.pdf"] = DocumentRejectionReasons.EmbeddedFile,
        ["encrypted.pdf"] = DocumentRejectionReasons.Encrypted,
        ["escaped-js.pdf"] = DocumentRejectionReasons.ActiveContent,
        ["escaped-js-lowercase-hex.pdf"] = DocumentRejectionReasons.ActiveContent,
        ["escaped-javascript-all-hex.pdf"] = DocumentRejectionReasons.ActiveContent,
        ["escaped-openaction.pdf"] = DocumentRejectionReasons.ActiveContent,
        ["js-in-text-stream.pdf"] = DocumentRejectionReasons.ActiveContent,
        ["truncated.pdf"] = DocumentRejectionReasons.Truncated,
        ["polyglot-appended-zip.pdf"] = DocumentRejectionReasons.Truncated,
        ["polyglot-html-trailer-with-js.pdf"] = DocumentRejectionReasons.ActiveContent,
        ["polyglot-html-prefix.pdf"] = NotAPdf,

        // KNOWN MISS (documented on PdfDenyListScanner): /OpenAction + a /JS action inside a FlateDecode /ObjStm.
        ["known-miss-objstm-js.pdf"] = Accepted,
    };

    private static string CorpusDirectory => Path.Combine(AppContext.BaseDirectory, "Features", "Media", "Documents", "Corpus");

    public static IEnumerable<object[]> CorpusFiles() => Expected.Keys.Order(StringComparer.Ordinal).Select(name => new object[] { name });

    [Fact]
    public void TheCorpusOnDisk_IsExactlyTheFilesWithAPinnedVerdict()
    {
        Directory.EnumerateFiles(CorpusDirectory, "*.pdf").Select(Path.GetFileName)
            .Should().BeEquivalentTo(Expected.Keys, "every checked-in fixture has a pinned verdict, and every verdict has its fixture");
    }

    [Theory]
    [MemberData(nameof(CorpusFiles))]
    public void EveryCorpusFile_GetsItsPinnedVerdict_WithinTheTimeBudget(string fileName)
    {
        var bytes = File.ReadAllBytes(Path.Combine(CorpusDirectory, fileName));
        var expected = Expected[fileName];

        var sniffed = MediaSniffer.Sniff(bytes.AsSpan(0, Math.Min(bytes.Length, MediaSniffer.ReadHeadLength)));
        if (expected == NotAPdf)
        {
            (sniffed is null || sniffed.Kind != MediaKinds.Document).Should().BeTrue(
                "{0} has markup before its PDF header, so it is never typed as a document (415)", fileName);
            return;
        }

        sniffed.Should().NotBeNull("{0} is a PDF by its leading bytes", fileName);
        sniffed!.Kind.Should().Be(MediaKinds.Document);

        var stopwatch = Stopwatch.StartNew();
        var verdict = PdfDenyListScanner.Scan(bytes);
        stopwatch.Stop();

        stopwatch.Elapsed.Should().BeLessThan(TimeSpan.FromSeconds(2), "the scan is one bounded pass (no hang on hostile input)");
        if (expected == Accepted)
        {
            verdict.Should().Be(DocumentScanResult.Pass, "{0} carries no deny-listed construct the byte scan can see", fileName);
        }
        else
        {
            verdict.Accepted.Should().BeFalse("{0} carries a deny-listed construct", fileName);
            verdict.Reason.Should().Be(expected);
        }
    }

    [Theory]
    [MemberData(nameof(CorpusFiles))]
    public void TheVerdict_DoesNotDependOnHowTheBytesAreChunked(string fileName)
    {
        // The upload streams in reads of arbitrary size; a token split across two reads must be seen the same way.
        var bytes = File.ReadAllBytes(Path.Combine(CorpusDirectory, fileName));
        var whole = PdfDenyListScanner.Scan(bytes);

        foreach (var chunk in new[] { 1, 2, 3, 7, 64, 4096 })
        {
            var scan = new PdfDenyListScanner().Begin();
            for (var offset = 0; offset < bytes.Length; offset += chunk)
            {
                scan.Append(bytes.AsSpan(offset, Math.Min(chunk, bytes.Length - offset)));
            }

            scan.Complete().Should().Be(whole, "{0} fed in {1}-byte chunks gets the same verdict", fileName, chunk);
        }
    }

    [Fact]
    public void TheKnownMiss_IsAcceptedBecauseItsTokensAreOnlyInsideCompressedData()
    {
        // Pins WHY the known miss is accepted: no deny-listed name appears in the raw bytes at all — the /JS action and
        // the /OpenAction are inside the FlateDecode object stream. If this ever starts failing, the fixture changed.
        var raw = Encoding.Latin1.GetString(File.ReadAllBytes(Path.Combine(CorpusDirectory, "known-miss-objstm-js.pdf")));

        raw.Should().Contain("/Type /ObjStm").And.Contain("/FlateDecode");
        foreach (var name in PdfDenyListScanner.DeniedNames.Keys)
        {
            raw.Should().NotContain("/" + name + " ", "the deny-listed tokens exist only in compressed form");
        }
    }
}
